const eventTypes={PushEvent:['↗','Código actualizado'],CreateEvent:['+','Nuevo recurso'],PullRequestEvent:['⇄','Pull request'],IssuesEvent:['◇','Issue'],ReleaseEvent:['⚑','Release publicada'],ForkEvent:['⑂','Repositorio bifurcado'],WatchEvent:['☆','Repositorio destacado'],DeleteEvent:['−','Recurso eliminado'],IssueCommentEvent:['☷','Comentario en una issue'],PullRequestReviewEvent:['✓','Revisión de código'],PublicEvent:['◉','Repositorio público']};
function renderEvent(e){const [icon,label]=eventTypes[e.type]||['·','Actividad en GitHub'];const item=make('div','activity-item'),body=make('div','activity-body'),title=make('strong'),a=make('a','',label+' · '+(e.repo?.name?.split('/').slice(1).join('/')||USER));const name=e.repo?.name;if(name&&/^[\w.-]+\/[\w.-]+$/.test(name))a.href=`https://github.com/${name}`;else a.href=`https://github.com/${USER}`;a.target='_blank';a.rel='noopener';title.append(a);body.append(title,make('p','',formatDate(e.created_at)));item.append(make('span','event-icon',icon),body);return item;}
function renderActivity(){const sorted=[...events].filter(e=>e.created_at).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));$('#activity-peek').replaceChildren(...sorted.slice(0,3).map(renderEvent));$('#activity-full').replaceChildren(...sorted.map(renderEvent));if(!sorted.length){for(const s of ['#activity-peek','#activity-full'])$(s).append(make('p','empty','No hay eventos públicos disponibles en esta ventana.'));}}
