function externalLink(url,label,cls){const a=make('a',cls,label);a.href=url;a.target='_blank';a.rel='noopener';return a;}
// README content is text from GitHub. Only a small safe Markdown subset is rendered;
// embedded HTML is displayed as text and remote images/scripts never execute.
function inlineMD(parent,text,repo=USER){text=text.replace(/\[!\[[^\]]*\]\([^)]*\)\]\([^)]*\)/g,'').replace(/!\[[^\]]*\]\([^)]*\)/g,'');const re=/(\[[^\]]*\]\([^\s)]+\))|(`[^`]+`)|(\*\*[^*]+\*\*)/g;let pos=0,m;while((m=re.exec(text))){parent.append(document.createTextNode(text.slice(pos,m.index)));const t=m[0];if(t.startsWith('[')){const name=t.slice(1,t.indexOf(']')),url=t.slice(t.indexOf('](')+2,-1);let safe;try{safe=url.startsWith('#')?`https://github.com/${USER}/${repo}${url}`:new URL(url,`https://github.com/${USER}/${repo}/blob/HEAD/`).href;}catch{}if(safe&&/^https?:\/\//.test(safe))parent.append(externalLink(safe,name,''));else parent.append(document.createTextNode(name));}else if(t.startsWith('`'))parent.append(make('code','',t.slice(1,-1)));else{const strong=make('strong');inlineMD(strong,t.slice(2,-2),repo);parent.append(strong);}pos=re.lastIndex;}parent.append(document.createTextNode(text.slice(pos)));}
function renderMD(text,target,repo=USER){target.replaceChildren();let code=null,paragraph=null;const lines=text.split('\n');for(let i=0;i<lines.length;i++){const line=lines[i];if(/^\s*```/.test(line)){paragraph=null;if(code){target.append(code);code=null;}else code=make('pre');continue;}if(code){code.textContent+=line+'\n';continue;}if(!line.trim()){paragraph=null;continue;}if(/^\s*</.test(line)||/^\s*[-_*]{3,}\s*$/.test(line)){paragraph=null;continue;}const h=line.match(/^(#{1,6})\s+(.+)/);if(h){paragraph=null;const node=make('h'+Math.min(3,h[1].length));inlineMD(node,h[2],repo);target.append(node);continue;}if(line.includes('|')&&/^\s*\|?\s*:?-{3,}/.test(lines[i+1]||'')){paragraph=null;const table=make('table'),thead=make('thead'),tbody=make('tbody');const cells=s=>s.trim().replace(/^\||\|$/g,'').split('|');const row=(s,tag)=>{const tr=make('tr');cells(s).forEach(v=>{const td=make(tag);inlineMD(td,v.trim(),repo);tr.append(td);});return tr;};thead.append(row(line,'th'));i++;while(i+1<lines.length&&lines[i+1].trim().startsWith('|'))tbody.append(row(lines[++i],'td'));table.append(thead,tbody);target.append(table);continue;}if(/^\s*[-*]\s/.test(line)){paragraph=null;const node=make('p');inlineMD(node,'• '+line.replace(/^\s*[-*]\s+/,''),repo);target.append(node);continue;}if(!paragraph){paragraph=make('p');target.append(paragraph);}else paragraph.append(document.createTextNode(' '));inlineMD(paragraph,line,repo);}if(code)target.append(code);}
async function api(path){const r=await fetch(`https://api.github.com/${path}`,{headers:{Accept:'application/vnd.github+json'},signal:AbortSignal.timeout(10000)});if(!r.ok)throw new Error(`GitHub ${r.status}`);return r.json();}
function decodeReadme(data){const bytes=Uint8Array.from(atob(data.content.replace(/\s/g,'')),c=>c.charCodeAt(0));return new TextDecoder().decode(bytes);}
