async function refresh(){const button=$('#refresh');button.disabled=true;const result=await Promise.allSettled([api(`users/${USER}`),api(`users/${USER}/events/public?per_page=30`),...PROJECTS.map(p=>api(`repos/${USER}/${p.repo}`))]);let count=0;if(result[0].status==='fulfilled'){profile=result[0].value;count++;}if(result[1].status==='fulfilled'){events=result[1].value;count++;}result.slice(2).forEach(r=>{if(r.status==='fulfilled'){repos=repos.filter(x=>x.name!==r.value.name);repos.push(r.value);count++;}});renderProfile();renderActivity();renderQuests();$('#data-status').textContent=count===8?`GitHub conectado · ${formatDate(new Date().toISOString())}`:count?`Actualización parcial · copia del ${formatDate(seed.fetchedAt)}`:`Copia del ${formatDate(seed.fetchedAt)} · GitHub no disponible`;button.disabled=false;}
