function path(x1,y1,x2,y2){const steps=Math.ceil(Math.hypot(x2-x1,y2-y1)/8);for(let i=0;i<=steps;i++){const x=Math.round((x1+(x2-x1)*i/steps)/8)*8,y=Math.round((y1+(y2-y1)*i/steps)/8)*8;rect(g,x-13,y-9,26,19,'#bec791');rect(g,x-9,y-7,20,14,'#d9d7a8');if(i%3===0)rect(g,x-3,y,5,3,'#c7c595');}}
