function drawTerrain(){rect(g,0,0,960,500,'#bad9cd');for(let i=0;i<70;i++){const x=Math.round(random()*960/8)*8,y=Math.round(random()*500/8)*8;rect(g,x,y,20+Math.floor(random()*3)*8,3,'#c9e1d5');}polygon(g,island,'#83b7a5',17);polygon(g,island,'#e2d7aa',8);polygon(g,island,'#abc384');polygon(g,[[145,146],[340,120],[701,123],[827,206],[854,342],[723,391],[356,405],[118,329]],'#b6cb8d');path(205,203,430,279);path(430,279,466,175);path(466,175,742,208);path(742,208,811,364);path(811,364,556,399);path(556,399,430,279);path(430,279,219,385);for(let i=0;i<230;i++){const x=95+random()*770,y=100+random()*314;rect(g,x,y,3,2,random()>.5?'#9cb779':'#c4d798');if(i%7===0){rect(g,x,y-3,3,3,'#f4e3ab');rect(g,x+4,y+1,2,2,'#e8cc8d');}}const positions=[[110,188],[104,252],[142,282],[154,116],[302,130],[348,102],[390,123],[584,113],[638,115],[689,135],[820,156],[862,244],[871,292],[734,365],[697,411],[635,403],[455,406],[385,379],[316,385],[170,395],[136,345],[290,262],[641,274],[656,303],[699,290]];positions.forEach(([x,y],i)=>tree(x,y,i%3===0?.85:1));for(let i=0;i<14;i++)bush(180+random()*600,210+random()*115);rect(g,359,303,79,5,'#9cac71');roof(363,292,65,'#dbc291');rect(g,363,298,65,4,'#a9946c');rect(g,392,279,8,20,'#766f4b');rect(g,413,277,16,19,'#927f54');rect(g,417,281,8,10,'#dabc76');rect(g,433,291,16,7,'#697850');rect(g,437,283,8,8,'#e5a95a');PROJECTS.forEach(building);rect(g,72,342,70,11,'#a18e67');for(let i=0;i<6;i++)rect(g,78+i*10,342,2,11,'#c2ae7d');rect(g,78,333,4,13,'#8e805f');rect(g,129,333,4,13,'#8e805f');}
