canvas.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright','w','a','s','d','enter'].includes(k)){e.preventDefault();targetPoint=null;if(k==='enter'){const p=PROJECTS.reduce((a,b)=>Math.hypot(hero.x-a.x,hero.y-(a.y+42))<Math.hypot(hero.x-b.x,hero.y-(b.y+42))?a:b);if(Math.hypot(hero.x-p.x,hero.y-(p.y+42))<85)openProject(p);else toast('Acércate a un edificio o toca su nombre para entrar.');}else keys.add(k);}});
canvas.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));canvas.addEventListener('blur',()=>keys.clear());window.addEventListener('blur',()=>keys.clear());
$('#home').addEventListener('click',()=>{hero.x=459;hero.y=282;targetPoint=null;keys.clear();toast('De vuelta al campamento.');});
function drawHero(c,x,y,moving){const step=moving?Math.floor(walkTime/120)%2:0;rect(c,x-10,y+5,21,5,'#6e956880');rect(c,x-5,y-3,5,9+(step?2:0),'#374940');rect(c,x+2,y-3,5,9+(step?0:2),'#374940');rect(c,x-9,y-20,18,20,'#2f7358');rect(c,x-12,y-16,4,12,'#cba575');rect(c,x+9,y-16,4,12,'#cba575');rect(c,x-8,y-34,16,15,'#deb07e');rect(c,x-10,y-39,20,8,'#43473c');rect(c,x-10,y-34,4,10,'#43473c');rect(c,x-5,y-27,3,3,'#3e4b40');rect(c,x+3,y-27,3,3,'#3e4b40');rect(c,x+6,y-17,7,13,'#8b8356');}
function frame(t){const dt=Math.min((t-lastTime)/1000||0,.05);lastTime=t;let dx=0,dy=0,moving=false;if(view==='world'&&!$('#project-dialog').open){if(targetPoint){const diffX=targetPoint.x-hero.x,diffY=targetPoint.y-hero.y,dist=Math.hypot(diffX,diffY);if(dist<5){const p=targetPoint.project;targetPoint=null;if(p)openProject(p);}else{dx=diffX/dist;dy=diffY/dist;}}else{dx=Number(keys.has('d')||keys.has('arrowright'))-Number(keys.has('a')||keys.has('arrowleft'));dy=Number(keys.has('s')||keys.has('arrowdown'))-Number(keys.has('w')||keys.has('arrowup'));const len=Math.hypot(dx,dy);if(len){dx/=len;dy/=len;}}if(dx||dy){const x=hero.x+dx*180*dt,y=hero.y+dy*180*dt;if(inside(x,y)){hero.x=x;hero.y=y;moving=true;walkTime+=dt*1000;}else targetPoint=null;}}if(view==='world'){ctx.drawImage(terrain,0,0);if(!matchMedia('(prefers-reduced-motion: reduce)').matches){for(let i=0;i<12;i++){const x=(t/70+i*89)%960,y=32+(i%3)*153;if(!inside(x,y))rect(ctx,x,y,22,2,'#d8eade80');}}drawHero(ctx,Math.round(hero.x/2)*2,Math.round(hero.y/2)*2,moving);}requestAnimationFrame(frame);}
updateProgress();renderProfile();renderActivity();$('#data-status').textContent=`Copia del ${formatDate(seed.fetchedAt)}`;const initial=location.hash.slice(1);if(['world','quests','journal','character'].includes(initial))setView(initial);requestAnimationFrame(frame);refresh();

if(document.body.classList.contains('embedded')){
  let lastReportedHeight=0;
  const reportWorldHeight=()=>{
    const height=Math.ceil(document.body.getBoundingClientRect().height)+8;
    if(height===lastReportedHeight)return;
    lastReportedHeight=height;
    window.parent.postMessage({type:'armesto-world-height',height},location.origin);
  };
  new ResizeObserver(reportWorldHeight).observe(document.body);
  window.addEventListener('load',reportWorldHeight);
  reportWorldHeight();
}
